pub const BisimulationRelation = struct {
    low_equiv_states: ArrayList(Pair(SystemState, SystemState)),

    pub fn checkNonInterference(self: *Self, high_action: Action) !bool {
        for (self.low_equiv_states.items) |pair| {
            const state1_after = executeAction(pair.first, high_action);
            const state2_after = executeAction(pair.second, high_action);

            // Check if low observations still equivalent
            if (!lowObservationsEqual(state1_after, state2_after)) {
                return false; // Interference detected!
            }
        }
        return true;
    }
};
```
