pub fn computeFractalDimension(graph: *SelfSimilarRelationalGraph) f64 {
    // Box-counting method approximation
    // D = log(N) / log(1/ε)
    // where N = number of boxes of size ε needed to cover graph

    var degree_dist = std.ArrayList(usize).init(allocator);
    defer degree_dist.deinit();

    for (graph.nodes.values()) |node| {
        degree_dist.append(graph.getDegree(node.id));
    }

    // Log-log regression slope
    // log(P(k)) ~ -α log(k)  →  D ≈ α
    return logLogSlope(degree_dist.items);
